"""Check native CPU and worker placement for one Bazel submission."""
import ast
import hashlib
import json
import os
from pathlib import Path
import re
import struct
import shlex
import subprocess
import sys
import uuid
import xml.etree.ElementTree as ET
from urllib.parse import unquote, urlparse

import exec_cas as cas


W = Path(os.environ["RUNNER_TEMP"]) / "mixed-native"
S = "de2430fdaeb26f743667ee569e15bec5e369ce63"
SDK = "//sandboxexec/sandbox/python:sandbox_py_test"
VDSO = "//vdso:vdso_test"
CPU = {"amd64": ("x86_64", 62), "arm64": ("aarch64", 183)}
T = {label+suffix: (cpu, kind) for label, kind in ((SDK,"sdk"), (VDSO,"vdso"))
     for cpu,suffix in (("amd64",""),("arm64","_presubmit_arm64"))}
PATTERNS = W / "python.targets"
PACKAGES = W / "python-packages.targets"
IMAGE = "docker://docker.io/library/ubuntu@sha256:b8b6ee6aa931ecd9d0d952abc34dc0e5f7c6a30c6bb71b079fe399fde0329c02"
BAZEL = [str(W/"bazel"),"--nosystem_rc","--nohome_rc","--host_jvm_args=-Xmx9500m"]
FLAGS = ["--config=source-presubmit-mixed", "--color=no", "--curses=no",
         "--nocache_test_results", "--flaky_test_attempts=1",
         "--modify_execution_info=^TestRunner$=+no-remote-cache"]
HEX = re.compile(r"[a-f0-9]{64}")
PUB = re.compile(r"//[A-Za-z0-9+._/-]*:[A-Za-z0-9+._/-]+")
TERMS = ("conflicting actions","action conflict","attempted to generate the same","generated by these conflicting","no matching toolchains",
         "no matching execution platform","exec format error","no registered executors","resource_exhausted",
         "resource exhausted","deadline exceeded","operation not permitted","no such file or directory",
         "unknown exec group","permission denied","undeclared inclusion","strict dependencies","out of memory","action failed","signal: killed")


def save(name,d):
    raw=json.dumps(d,sort_keys=True,indent=1)
    assert len(raw)<75000 and not re.search(r"(?i)authorization:|x-buildbuddy-api-key|github_pat_|gh[pousr]_[A-Za-z0-9]{20,}",raw)
    if "ACCESS" in os.environ:assert os.environ["ACCESS"] not in raw
    (W/"output"/(name+".json")).write_text(raw+"\n")


def read(name):
    return json.loads((W/"output"/(name+".json")).read_text())


def events(name):
    p=W/(name+".bep")
    if p.exists():
        with p.open() as f:
            for line in f:
                try:yield json.loads(line)
                except ValueError:return


def signal(path):
    words=set()
    if path.exists():
        with path.open(errors="replace") as f:
            for l in f:
                low=l.lower()
                words.update(t for t in TERMS if t in low)
    return sorted(words)


def call(cmd,phase,args,minutes,config="source-presubmit-mixed"):
    with (W/(phase+".stdout")).open("w") as out,(W/(phase+".log")).open("w") as err:
        secret=["--bazelrc="+str(W/"remote.rc")] if phase=="execute" else []
        return subprocess.run(["timeout","--signal=INT","--kill-after=45s",str(minutes)+"m",*BAZEL,*secret,cmd,"--config="+config,*FLAGS[1:],
                "--build_event_json_file="+str(W/(phase+".bep")),*args],stdout=out,stderr=err).returncode


def analyze():
    src=subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
    assert src==S
    assert "remote_default_exec_properties=Arch" not in Path(".bazelrc").read_text()
    PATTERNS.write_text("\n".join(T) + "\n")
    PACKAGES.write_text("//vdso/...\n//sandboxexec/sandbox/python/...\n")
    opts=["--spawn_strategy=local","--strategy=TestRunner=local","--jobs=4"]
    r={"source":S,"profiles":{},"eligible":False}
    for profile in ("source-presubmit", "source-presubmit-arm64", "source-presubmit-mixed"):
        phase="selection-"+profile
        code=call("test",phase,[*opts,"--target_pattern_file="+str(PACKAGES),"--nobuild","--build_tests_only"],9,profile)
        planned=set()
        for e in events(phase):
            t=e["id"].get("targetCompleted",{})
            if t and not t.get("aspect") and e.get("aborted",{}).get("reason")=="NO_BUILD":
                planned.add(t["label"])
        expected=set(T) if profile.endswith("mixed") else {SDK,VDSO}
        r["profiles"][profile]={"exit":code,"selected":sorted(t for t in planned if PUB.fullmatch(t)),
            "ok":code in (0,1) and planned==expected,"signals":signal(W/(phase+".log"))}
        save("selection",r)
    r["selection_ok"]=all(p["ok"] for p in r["profiles"].values())
    if not r["selection_ok"]:return
    query = 'mnemonic("^TestRunner$",set(' + ' '.join(T) + '))'
    code=call("aquery","graph",[*opts,"--output=jsonproto","--include_artifacts=false",query],10)
    r.update(graph_exit=code,graph_signals=signal(W/"graph.log"),tests={})
    save("selection",r)
    if code:return
    data=json.loads((W/"graph.stdout").read_text())
    targets={str(t["id"]):t["label"] for t in data["targets"]}
    for a in data.get("actions",[]):
        label=targets[str(a["targetId"])]
        if a["mnemonic"]!="TestRunner" or label not in T:
            continue
        cpu,_=T[label]
        platform=a.get("executionPlatform","").removeprefix("@@")
        isolation={v["key"]:v.get("value","") for v in a.get("executionInfo",[])}.get("workload-isolation-type","oci")
        r["tests"].setdefault(label,[]).append({
            "platform":platform if PUB.fullmatch(platform) else None,
            "isolation":isolation if isolation in ("oci","firecracker") else "other",
            "matches":platform=="//test/rbe:ubuntu_"+cpu and isolation==("firecracker" if T[label][1]=="sdk" else "oci"),
        })
    r["eligible"]=r["tests"].keys()==T.keys() and all(
        len(actions)==1 and actions[0]["matches"] for actions in r["tests"].values())
    save("selection",r)


# Use the checker's own declared readelf for artifact identification. Bash
# supplies its compiled-in CPU. The SDK runs its original unittest main in
# verbose mode so an intentionally skipped method remains distinguishable.
WITNESS = r'''set -eu
printf 'MAINTAINED_PY_CPU %s\n' "$HOSTTYPE"
case "${TEST_TARGET:-$1}" in
  *sandbox_py_test*) exec "$@" -v ;;
  *vdso_test*)
    reader= image= data=0
    for a in "$@"; do
      case "$a" in --readelf=*) reader=${a#*=} ;; --vdso=*) image=${a#*=} ;; --check-data) data=1 ;; esac
    done
    test "$data" = 1
    "$reader" -h "$image"
    printf 'MAINTAINED_PY_TEXT_BEGIN\n'
    "$reader" -x .text "$image"
    printf 'MAINTAINED_PY_TEXT_END\n'
    exec "$@" ;;
  *) exit 19 ;;
esac'''


def execute():
    assert read("selection")["eligible"] and PATTERNS.read_text().splitlines()==list(T)
    outputs = "|".join(label[2:].replace(":","/") for label in T)
    code=call("test","execute",["--jobs=48","--keep_going","--remote_download_outputs=minimal",
        "--target_pattern_file="+str(PATTERNS),
        "--run_under=bash -c "+shlex.quote(WITNESS)+" observe",
        "--remote_download_regex=.*(testlogs/("+outputs+")/test[.](xml|log)|bin/vdso/vdso[.]so)$"],42)
    save("exit",{"source":S,"exit":code,"signals":signal(W/"execute.log")})


def output_log(label, output):
    uri=urlparse(output.get("uri",""))
    d=re.search(r"/(?:blobs|compressed-blobs/zstd)/([a-f0-9]{64})/(\d+)$",uri.path)
    ref=(d[1],int(d[2])) if d else (output.get("digest"),int(output.get("length",0)))
    name=output["name"]
    paths=([Path(unquote(uri.path))] if uri.scheme=="file" else [])
    sub=label[2:].replace(":","/")+"/"+name
    paths.extend(Path("bazel-out").glob("*/testlogs/"+sub))
    for p in paths:
        if p.is_file() and p.stat().st_size<=5*1024*1024:
            raw=p.read_bytes();digest=hashlib.sha256(raw).hexdigest()
            if ref[0] and ref!=(digest,len(raw)):continue
            return raw,digest
    return None,None


def sdk_methods():
    code=Path("sandboxexec/sandbox/python/tests/sandbox_test.py").read_text()
    suite=next(c for c in ast.parse(code).body if isinstance(c,ast.ClassDef) and c.name=="SandboxTest")
    return sorted(n.name for n in suite.body if isinstance(n,ast.FunctionDef) and n.name.startswith("test_"))


def vdso_outputs():
    items=[]
    for path in sorted(Path("bazel-out").glob("*/bin/vdso/vdso.so")):
        if not path.is_file() or not 64<=path.stat().st_size<=1024*1024:continue
        image=path.read_bytes()
        if image[:6]!=b"\x7fELF\x02\x01":continue
        machine=struct.unpack_from("<H",image,18)[0]
        offset=struct.unpack_from("<Q",image,40)[0]
        stride,num,idx=struct.unpack_from("<3H",image,58)
        if stride!=64 or not(idx<num<=260) or offset+stride*num>len(image):continue
        sections=[struct.unpack_from("<IIQQQQIIQQ",image,offset+i*stride) for i in range(num)]
        ns=sections[idx]; names=image[ns[4]:ns[4]+ns[5]]
        for section in sections:
            if names[section[0]:].split(b"\0",1)[0]!=b".text":continue
            body=image[section[4]:section[4]+section[5]]
            if not body or len(body)!=section[5]:continue
            items.append({"machine":machine,"sha256":hashlib.sha256(image).hexdigest(),
                "text_sha256":hashlib.sha256(body).hexdigest(),"size":len(image)})
    return items


def observed_log(raw,cpu,kind,methods):
    text=raw.decode(errors="replace")
    arch,machine=CPU[cpu]
    out={"native_shell":re.findall(r"^MAINTAINED_PY_CPU ([A-Za-z0-9_]+)$",text,re.M)==[arch]}
    if kind=="sdk":
        cases={m:[] for m in methods}
        current=None
        for line in text.splitlines():
            match=re.match(r"^(test_[A-Za-z0-9_]+) \(.*?\)",line)
            if match:current=match[1] if match[1] in cases else None
            if current:
                status=re.search(r"(?:\.\.\. |^)(ok|skipped|FAIL|ERROR)\b",line)
                if status:
                    cases[current].append(status[1])
                    current=None
        out["methods"]=cases
        out["case_match"]=all(v==(["skipped"] if m=="test_non_root_networking_error" else ["ok"]) for m,v in cases.items())
    else:
        hdr=re.search(r"^ *Machine: *(.*?) *$",text,re.M)
        out["header_matches"]=bool(hdr and ("aarch64" in hdr[1].lower() if machine==183 else "x86-64" in hdr[1].lower()))
        begin,sep,rest=text.partition("MAINTAINED_PY_TEXT_BEGIN\n")
        code,done,end=rest.partition("MAINTAINED_PY_TEXT_END\n")
        data=bytearray()
        if sep and done:
            for line in code.splitlines():
                fields=line.split()
                if not fields or not re.fullmatch(r"0x[0-9a-fA-F]+",fields[0]):continue
                # LLVM and GNU readelf both print up to four words before ASCII.
                for word in fields[1:5]:
                    if not re.fullmatch(r"(?:[a-fA-F0-9]{2}){1,4}",word):break
                    data+=bytes.fromhex(word)
        out["text_sha256"]=hashlib.sha256(data).hexdigest() if data else None
    return out


def collect():
    r={"source":S,"test_results":{},"errors":[],"builds":{},"summaries":{},"verified":False}
    for e in events("execute"):
        ids=e["id"]
        if "started" in e:r["invocation"]=str(uuid.UUID(e["started"]["uuid"]))
        if "finished" in e:r["bazel_exit"]=int(e["finished"].get("exitCode",{}).get("code",0))
        t=ids.get("targetCompleted",{})
        if t.get("label") in T and not t.get("aspect"):
            r["builds"][t["label"]]=e["completed"].get("success",False) if "completed" in e else None
        if "action" in e and not e["action"].get("success",False) and len(r["errors"])<14:
            own=ids.get("actionCompleted",{}).get("label","")
            typ=e["action"].get("type","")
            uri=e["action"].get("stderr",{}).get("uri","")
            d=re.search(r"/blobs/([a-f0-9]{64})/(\d+)$",uri)
            r["errors"].append({"owner":own if PUB.fullmatch(own) else "dependency","mnemonic":typ if re.fullmatch(r"[a-zA-Z0-9_]+",typ) else "other",
                 "stderr":[d[1],int(d[2])] if d else None})
        label=ids.get("testSummary",{}).get("label","")
        if label in T and "testSummary" in e:r["summaries"][label]=e["testSummary"].get("overallStatus")=="PASSED"
        label=ids.get("testResult",{}).get("label","")
        if label not in T or "testResult" not in e:continue
        t=e["testResult"];info=t.get("executionInfo",{});cpu,kind=T[label]
        row={"passed":t.get("status")=="PASSED","remote":info.get("strategy")=="remote",
             "cached":bool(t.get("cachedLocally") or info.get("cachedRemotely"))}
        r["test_results"].setdefault(label,[]).append(row)
        for item in t.get("testActionOutput",[]):
            name=item.get("name")
            if name not in ("test.log","test.xml"):continue
            raw,digest=output_log(label,item)
            if not raw:continue
            row[name+"_sha256"]=digest
            if name=="test.log":row.update(observed_log(raw,cpu,kind,sdk_methods()))
            else:
                try:row["xml_failed"]=any(e.tag in ("failure","error") for e in ET.fromstring(raw).iter())
                except ET.ParseError:pass
    r["elfs"]=vdso_outputs()
    for label,rows in r["test_results"].items():
        cpu,kind=T[label]
        for row in rows:
            if kind=="vdso":
                row["elf_matches"]=[v["sha256"] for v in r["elfs"] if v["machine"]==CPU[cpu][1] and v["text_sha256"]==row.get("text_sha256")]
            row["confirmed"]=bool(row["passed"] and row["remote"] and not row["cached"] and row.get("xml_failed") is False and row.get("native_shell")
                and (row.get("case_match") if kind=="sdk" else row.get("header_matches") and row.get("elf_matches")))
    r["verified"]=(r.get("bazel_exit")==0 and r["test_results"].keys()==T.keys() and all(
        r["builds"].get(k) and r["summaries"].get(k) and len(rows)==1 and rows[0]["confirmed"] for k,rows in r["test_results"].items()))
    save("test",r)


def platform_fields(message):
    p={}
    for k,v in cas.fields(message):
        if k==1:
            prop=dict(cas.fields(v))
            if 1 in prop and 2 in prop:p[prop[1].decode()]=prop[2].decode()
    return {"cpu":p.get("Arch") if p.get("Arch") in CPU else None,"linux":p.get("OSFamily")=="linux",
        "ubuntu":p.get("container-image")==IMAGE,
        "class":p.get("workload-isolation-type") if p.get("workload-isolation-type") in ("oci","firecracker") else None,
        "root":p.get("dockerUser")=="root","ipv6":p.get("network-enable-ipv6")=="true"}


def service():
    test=read("test"); plan=read("selection")
    assert test["source"]==S and plan["source"]==S and plan["eligible"]
    assert subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()==S
    # Only this workflow's source-bound BEP can select an invocation. No
    # service request is made for any other product or earlier submission.
    cas.INV=str(uuid.UUID(test["invocation"]))
    r={"source":S,"invocation":cas.INV,"workers":{},"diagnostics":{},"verified":False}
    for label in T:
        try:
            rows=cas.executions(label,"TestRunner")
            assert len(rows)<=15
            for e in rows:
                meta=e["actionDigest"]
                action=dict(cas.fields(cas.blob(meta,128*1024)))
                cmd=list(cas.fields(cas.blob(cas.digest_msg(action[1]),4*1024*1024)))
                args=[v.decode() for t,v in cmd if t==1]
                rep=e.get("executeResponse",{})
                if "result" not in rep:
                    continue
                out=rep["result"]
                if not (any(s.endswith("/test-setup.sh") for s in args) or
                    any(str(f.get("path","")).endswith("/test.cache_status") for f in out.get("outputFiles",[]))):
                    continue
                p=platform_fields(action[10]) if 10 in action else next((platform_fields(v) for t,v in cmd if t==5),{})
                row={"platform":p,"action_sha256":meta["hash"],"exit":out.get("exitCode",0),"rpc":rep.get("status",{}).get("code",0),
                     "cached":bool(rep.get("cachedResult")),"qemu":any("qemu-" in s for s in args)}
                cpu,kind=T[label]
                placement=p.get("class")=="oci" if kind=="vdso" else p.get("class")=="firecracker" and p.get("root") and p.get("ipv6")
                row["matches"]=(p.get("cpu")==cpu and placement and p.get("linux") and p.get("ubuntu")
                                and not row["cached"] and not row["rpc"] and not row["exit"] and not row["qemu"])
                r["workers"].setdefault(label,[]).append(row)
                save("workers",r)
        except (OSError,ValueError,KeyError,AssertionError,IndexError) as ex:
            r["diagnostics"][label]=type(ex).__name__
            save("workers",r)
    r["verified"]=(test["verified"] and r["workers"].keys()==T.keys() and
        all(len(r["workers"][k])==1 and r["workers"][k][0]["matches"] for k in T))
    save("workers",r)


if __name__=="__main__":
    {"analyze":analyze,"execute":execute,"collect":collect,"service":service}[sys.argv[1]]()
